-- Setup SE (Software Engineering) Exam System
-- Table 1: Student Verification Table (3rd Year CSE)
-- Table 2: Results Table

-- Drop existing tables if they exist
DROP TABLE IF EXISTS "3rdcsesesresults" CASCADE;
DROP TABLE IF EXISTS "3rdcsese" CASCADE;

-- Create Student Verification Table
CREATE TABLE "3rdcsese" (
    id SERIAL PRIMARY KEY,
    roll_number VARCHAR(20) UNIQUE NOT NULL,
    unique_code VARCHAR(20) NOT NULL DEFAULT 'se771',
    is_active BOOLEAN DEFAULT TRUE,
    verified_at TIMESTAMP,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Create Results Table
CREATE TABLE "3rdcsesesresults" (
    id SERIAL PRIMARY KEY,
    roll_number VARCHAR(20) NOT NULL,
    correct_answers INTEGER NOT NULL,
    wrong_answers INTEGER NOT NULL,
    total_questions INTEGER NOT NULL DEFAULT 10,
    marks DECIMAL(5,2) NOT NULL,
    percentage DECIMAL(5,2) NOT NULL,
    user_answers JSONB,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (roll_number) REFERENCES "3rdcsese"(roll_number) ON DELETE CASCADE
);

-- Insert all 246 roll numbers with unique code 'se771' (same students as ALC/CS)

-- Create indexes for better performance
CREATE INDEX idx_se_roll_number ON "3rdcsese"(roll_number);
CREATE INDEX idx_se_results_roll_number ON "3rdcsesesresults"(roll_number);
CREATE INDEX idx_se_created_at ON "3rdcsesesresults"(created_at);

-- Verify data
SELECT COUNT(*) as total_students FROM "3rdcsese";
